// Generate the Claude Code skill mirror from the vendor-neutral agent surface
// (task-vendor-neutral-interop). The canonical skill text lives under
// `.konspekt/agents/skills/<name>/SKILL.md` so another vendor's tooling can
// discover it; Claude Code only auto-loads skills from `.claude/skills/`, so
// this mirrors each neutral skill into `.claude/skills/<name>/SKILL.md` with an
// AUTOGENERATED banner. The mirror is a generated adapter, like ROADMAP.md: the
// neutral file is the single source of truth, and `--check` fails when a mirror
// is missing or stale.
//
// Usage (from the repo root):
//   node tools/sync-agents.mjs            # write/refresh the mirrors
//   node tools/sync-agents.mjs --check    # verify; exit 1 if any mirror is stale
//   node tools/sync-agents.mjs [neutralDir] [mirrorDir]

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const argv = process.argv.slice(2);
const positional = argv.filter((a) => !a.startsWith("--"));
const check = argv.includes("--check");
const NEUTRAL = positional[0] || ".konspekt/agents/skills";
const MIRROR = positional[1] || ".claude/skills";

const norm = (s) => s.replace(/\r\n/g, "\n");

// The mirror is the neutral source with a banner inserted just after its YAML
// frontmatter (so the skill's name/description still parse for discovery).
function render(srcText, name) {
  const banner =
    `<!-- AUTOGENERATED by tools/sync-agents.mjs from ${NEUTRAL}/${name}/SKILL.md\n` +
    `     Do not edit this mirror; edit the neutral source and re-run tools/sync-agents.mjs. -->\n`;
  const src = norm(srcText);
  const m = src.match(/^---\n[\s\S]*?\n---\n/);
  if (m) return m[0] + banner + src.slice(m[0].length);
  return banner + src;
}

function skillNames(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((n) => existsSync(join(dir, n, "SKILL.md"))).sort();
}

const names = skillNames(NEUTRAL);
const stale = [];
for (const name of names) {
  const want = render(readFileSync(join(NEUTRAL, name, "SKILL.md"), "utf8"), name);
  const dest = join(MIRROR, name, "SKILL.md");
  const have = existsSync(dest) ? norm(readFileSync(dest, "utf8")) : null;
  if (check) {
    if (have !== want) stale.push(have === null ? `${name} (missing)` : name);
  } else {
    mkdirSync(join(MIRROR, name), { recursive: true });
    writeFileSync(dest, want, "utf8");
  }
}

if (check) {
  if (stale.length) {
    console.error(`sync-agents --check: stale or missing mirror for: ${stale.join(", ")}`);
    console.error("Regenerate and commit:  node tools/sync-agents.mjs");
    process.exit(1);
  }
  console.log(`sync-agents --check: ${names.length} skill mirror(s) up to date.`);
} else {
  console.log(`sync-agents: wrote ${names.length} skill mirror(s) to ${MIRROR}/: ${names.join(", ")}`);
}
